    private static String music(int value,String secret){JsonObject state=new JsonObject(),hud=new JsonObject(),auth=new JsonObject();hud.addProperty("value",value);hud.addProperty("cookie",secret);auth.addProperty("cookie",secret);state.add("hud",hud);state.add("auth",auth);JsonObject result=new JsonObject();result.addProperty("format","muonium.profile.music");result.addProperty("version",1);result.addProperty("localOnly",true);result.addProperty("cookie",secret);result.add("state",state);return result.toString();}
    static final class Queue implements Executor{final ArrayDeque<Runnable> tasks=new ArrayDeque<>();final String name;Queue(String name){this.name=name;}public void execute(Runnable task){tasks.add(task);}void one(){Runnable next=tasks.poll();if(next==null)return;String previous=Thread.currentThread().getName();Thread.currentThread().setName(name);try{next.run();}finally{Thread.currentThread().setName(previous);}}}
